def true_date(url):
    m = re.search(r'(?:activity|ugcPost|share)[-:](\d{18,20})', url)
    if not m: return ""
    return datetime.datetime.fromtimestamp((int(m.group(1)) >> 22) / 1000, datetime.UTC).strftime("%Y-%m-%d")

with open(OUT, "w", newline="", encoding="utf-8") as f:
    w = csv.writer(f)
